// readConnectionData reads the details of the process that is connecting. The 2023.08.10
// Juice client predates them and sends an empty form instead. Its connections all share the
// session's id, so they reach one Renderer_Win per session, as with the agent of that release.
func readConnectionData(sessionId string, r *http.Request) (restapi.ConnectionData, error) {
	if r.Header.Get("Content-Type") != "application/json" {
		_, err := io.Copy(io.Discard, r.Body)
		return restapi.ConnectionData{Id: sessionId, ProcessName: "juice"}, err
	}

	return pkgnet.ReadRequestBody[restapi.ConnectionData](r)
}

