fn proc_addresses_follow_cuda_versions() {
    assert_eq!(proc_address("cuMemAlloc", 13040, false), Ok("cuMemAlloc_v2"));
    assert_eq!(proc_address("cuMemAlloc", 2000, false), Ok("cuMemAlloc"));
    assert_eq!(proc_address("cuCtxCreate", 2000, false), Ok("cuCtxCreate"));
    assert_eq!(proc_address("cuCtxCreate", 3020, false), Ok("cuCtxCreate_v2"));
    assert_eq!(proc_address("cuCtxCreate", 13040, false), Ok("cuCtxCreate_v4"));
    assert_eq!(proc_address("cuGetProcAddress", 11030, false), Ok("cuGetProcAddress"));
    assert_eq!(proc_address("cuGetProcAddress", 12000, false), Ok("cuGetProcAddress_v2"));
    assert_eq!(proc_address("cuMemcpyHtoD", 13040, false), Ok("cuMemcpyHtoD_v2"));
    assert_eq!(proc_address("cuMemcpyHtoD", 13040, true), Ok("cuMemcpyHtoD_v2_ptds"));
    assert_eq!(proc_address("cuInit", 13040, true), Ok("cuInit"), "no per-thread variant: the usual one");
    assert_eq!(proc_address("cuMemAllocAsync", 11000, false), Err(VERSION_NOT_SUFFICIENT));
    assert_eq!(proc_address("cuNotAFunction", 13040, false), Err(SYMBOL_NOT_FOUND));
}

