/// The export cuGetProcAddress returns for each symbol, per (CUDA version, flags), as the
/// lender's driver decides it
type ResolveTable = HashMap<String, (c_int, String)>;

fn resolve(symbol: &str, version: c_int, flags: cuuint64_t) -> Option<(c_int, Option<String>)> {
    static TABLES: Mutex<Option<HashMap<(c_int, cuuint64_t), ResolveTable>>> = Mutex::new(None);

    let mut tables = TABLES
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let tables = tables.get_or_insert_with(HashMap::new);

    let table = match tables.entry((version, flags)) {
        Entry::Occupied(entry) => entry.into_mut(),
        Entry::Vacant(entry) => {
            let reply = call(
                protocol::RESOLVE,
                &[args(|w| {
                    w.i32(version).u64(flags);
                })
                .as_slice()],
            )
            .ok()?;

            let mut reader = Reader::new(&reply);
            let mut table = HashMap::new();
            let count = reader.u32().ok()?;
            for _ in 0..count {
                let symbol = String::from_utf8_lossy(reader.bytes().ok()?).into_owned();
                let status = reader.i32().ok()?;
                let export = String::from_utf8_lossy(reader.bytes().ok()?).into_owned();
                table.insert(symbol, (status, export));
            }
            entry.insert(table)
        }
    };

    Some(match table.get(symbol) {
        Some((status, export)) if export.is_empty() => (*status, None),
        Some((status, export)) => (*status, Some(export.clone())),
        None => (CU_GET_PROC_ADDRESS_SYMBOL_NOT_FOUND as c_int, None),
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cuGetProcAddress_v2(
    symbol: *const c_char,
    pfn: *mut *mut c_void,
    cudaVersion: c_int,
    flags: cuuint64_t,
    symbolStatus: *mut CUdriverProcAddressQueryResult,
) -> CUresult {
    if symbol.is_null() || pfn.is_null() {
        return CUDA_ERROR_INVALID_VALUE;
    }
    let name = unsafe { CStr::from_ptr(symbol) }.to_string_lossy();

    // Without a lender, offer the export of the same name, so the application gets as far
    // as cuInit and its CUDA_ERROR_NO_DEVICE
    let (status, export) = resolve(&name, cudaVersion, flags).unwrap_or_else(|| {
        if generated::exports().contains_key(&*name) {
            (CU_GET_PROC_ADDRESS_SUCCESS as c_int, Some(name.to_string()))
        } else {
            (CU_GET_PROC_ADDRESS_SYMBOL_NOT_FOUND as c_int, None)
        }
    });

    let address = export.and_then(|export| generated::exports().get(export.as_str()).copied());
    unsafe {
        *pfn = address.map_or(ptr::null_mut(), |address| address.cast_mut());
        if !symbolStatus.is_null() {
            *symbolStatus = match address {
                Some(_) => CU_GET_PROC_ADDRESS_SUCCESS,
                None if status == CU_GET_PROC_ADDRESS_SUCCESS as c_int => {
                    CU_GET_PROC_ADDRESS_SYMBOL_NOT_FOUND
                }
                None => status as CUdriverProcAddressQueryResult,
            };
        }
    }

    if address.is_some() {
        CUDA_SUCCESS
    } else {
        CUDA_ERROR_NOT_FOUND
    }
}

