/// Hands out this library's wrapper in place of the real function, so calls made through
/// the pointer are traced too
unsafe fn substitute(
    symbol: *const c_char,
    pfn: *mut *mut c_void,
    version: c_int,
    flags: cuuint64_t,
) {
    let real = unsafe { *pfn } as usize;
    let export = driver()
        .and_then(|driver| driver.index_by_address.get(&real))
        .map(|&index| NAMES[index]);
    if let Some(export) = export
        && let Some(&wrapper) = generated::exports().get(export)
    {
        unsafe { *pfn = wrapper.cast_mut() };
    }

    let symbol = unsafe { CStr::from_ptr(symbol) }
        .to_string_lossy()
        .into_owned();
    let export = export.unwrap_or("(not an export)").to_string();
    with_trace(|trace| trace.lookups.push((symbol, version, flags, export)));
}

