/// Where the hybrid runtime may be: NECTAR_CUDA_HYBRID, next to this library, System32, then
/// the NVIDIA display driver's DriverStore folders, newest first. It ships with NVIDIA's
/// display driver only, not with the CUDA toolkit.
fn hybrid_candidates(name: &str) -> Vec<std::path::PathBuf> {
    use std::path::PathBuf;

    let mut candidates = Vec::new();
    if let Some(path) = env::var_os("NECTAR_CUDA_HYBRID") {
        candidates.push(PathBuf::from(path));
    }

    // This library's own folder
    let mut module = ptr::null_mut();
    let mut path = [0u16; 1024];
    unsafe {
        use windows_sys::Win32::System::LibraryLoader::{
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS, GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, GetModuleFileNameW,
            GetModuleHandleExW,
        };
        if GetModuleHandleExW(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
            hybrid_candidates as *const u16,
            &mut module,
        ) != 0
        {
            let length = GetModuleFileNameW(module, path.as_mut_ptr(), path.len() as u32) as usize;
            if let Some(folder) = PathBuf::from(String::from_utf16_lossy(&path[..length])).parent() {
                candidates.push(folder.join(name));
            }
        }
    }

    let system = env::var_os("SystemRoot").map(PathBuf::from).unwrap_or_else(|| PathBuf::from(r"C:\Windows"));
    candidates.push(system.join("System32").join(name));

    let mut stored: Vec<(std::time::SystemTime, PathBuf)> = std::fs::read_dir(system.join(r"System32\DriverStore\FileRepository"))
        .into_iter()
        .flatten()
        .flatten()
        .filter(|entry| entry.file_name().to_string_lossy().starts_with("nv"))
        .map(|entry| entry.path().join(name))
        .filter_map(|path| Some((std::fs::metadata(&path).ok()?.modified().ok()?, path)))
        .collect();
    stored.sort();
    candidates.extend(stored.into_iter().rev().map(|(_, path)| path));
    candidates
}

