#[test]
fn large_messages_are_compressed_when_they_shrink() {
    let head = [7u8; 16];
    let zeros = vec![0u8; 1 << 20];
    let mut wire = Vec::new();
    write_message(&mut wire, 42, &[&head, &zeros], true).unwrap();
    assert!(wire.len() < 64 << 10, "{} bytes", wire.len());
    let (id, body) = read_message(&mut wire.as_slice()).unwrap();
    assert_eq!(id, 42);
    assert_eq!(body, [&head[..], &zeros].concat());

    // Bytes that do not shrink go as they are
    let mut state = 1u64;
    let noise: Vec<u8> = (0..1 << 20)
        .map(|_| {
            state = state.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            (state >> 56) as u8
        })
        .collect();
    let mut wire = Vec::new();
    write_message(&mut wire, 42, &[&noise], true).unwrap();
    assert_eq!(wire.len(), 8 + noise.len());
    assert_eq!(read_message(&mut wire.as_slice()).unwrap().1, noise);

    // Nor when compressing was not asked for
    let mut wire = Vec::new();
    write_message(&mut wire, 42, &[&zeros], false).unwrap();
    assert_eq!(wire.len(), 8 + zeros.len());
}

