/// so several messages can go out together. With `compress`, a large message whose sample
/// shrinks is compressed.
pub fn write_message(
    stream: &mut impl Write,
    head: u32,
    parts: &[&[u8]],
    compress: bool,
) -> io::Result<()> {
    let size = parts.iter().map(|part| part.len()).sum::<usize>();
    if 4 + size > MAX_MESSAGE {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "message too large",
        ));
    }

    if compress
        && size >= COMPRESS_MIN
        && let Some(packed) = compressed(parts, size)
    {
        stream.write_all(&((8 + packed.len()) as u32 | COMPRESSED).to_le_bytes())?;
        stream.write_all(&head.to_le_bytes())?;
        stream.write_all(&(size as u32).to_le_bytes())?;
        return stream.write_all(&packed);
    }

    stream.write_all(&((4 + size) as u32).to_le_bytes())?;
    stream.write_all(&head.to_le_bytes())?;
    for part in parts {
        stream.write_all(part)?;
    }
    Ok(())
}

/// The parts as one LZ4 block, if compressing pays: data such as model weights and float
/// results hardly shrinks, so a sample of the largest part is tried first. LZ4 compresses
/// at gigabytes a second, far faster than Wi-Fi carries data.
fn compressed(parts: &[&[u8]], size: usize) -> Option<Vec<u8>> {
    let largest = parts.iter().max_by_key(|part| part.len())?;
    let sample = &largest[..largest.len().min(COMPRESS_MIN)];
    let mut packed = vec![0u8; lz4_flex::block::get_maximum_output_size(size)];
    let shrunk = lz4_flex::block::compress_into(sample, &mut packed).ok()?;
    if shrunk * 10 > sample.len() * 9 {
        return None;
    }

    let whole = parts.concat();
    let shrunk = lz4_flex::block::compress_into(&whole, &mut packed).ok()?;
    if shrunk * 10 > size * 9 {
        return None;
    }
    packed.truncate(shrunk);
    Some(packed)
}

/// Reads a message and returns its head and body
pub fn read_message(stream: &mut impl Read) -> io::Result<(u32, Vec<u8>)> {
    let mut header = [0u8; 8];
    stream.read_exact(&mut header)?;

    let field = u32::from_le_bytes(header[..4].try_into().unwrap());
    let length = (field & !COMPRESSED) as usize;
    let invalid = |what: String| io::Error::new(io::ErrorKind::InvalidData, what);
    if !(4..=MAX_MESSAGE).contains(&length) {
        return Err(invalid(format!("message length {length}")));
    }

    let head = u32::from_le_bytes(header[4..].try_into().unwrap());
    let mut body = vec![0u8; length - 4];
    stream.read_exact(&mut body)?;

    if field & COMPRESSED == 0 {
        return Ok((head, body));
    }
    let Some((size, packed)) = body.split_first_chunk::<4>() else {
        return Err(invalid("compressed message without its size".into()));
    };
    let size = u32::from_le_bytes(*size) as usize;
    if size > MAX_MESSAGE - 4 {
        return Err(invalid(format!("compressed message of {size} bytes")));
    }
    let mut unpacked = vec![0u8; size];
    match lz4_flex::block::decompress_into(packed, &mut unpacked) {
        Ok(written) if written == size => Ok((head, unpacked)),
        _ => Err(invalid("corrupt compressed message".into())),
    }
}

